class CampusHomePage extends StatefulWidget {
  const CampusHomePage({super.key});

  @override
  State<CampusHomePage> createState() => _CampusHomePageState();
}

class _CampusHomePageState extends State<CampusHomePage> {
  // ----------------------------------------------------------
  // NAVIGATION STATE
  // ----------------------------------------------------------

  int currentIndex = 0;

  // Lets us open the end drawer from the app bar
  final GlobalKey<ScaffoldState> scaffoldKey = GlobalKey<ScaffoldState>();

  // Notification preference chosen in Settings (RadioListTile)
  // 0 = all, 1 = important only, 2 = off
  int notificationMode = 0;

  final List<String> pageTitles = [
    'AVIT Campus',
    'AVIT Activities',
    'My Profile',
  ];

  // ----------------------------------------------------------
  // PROFILE STATE (the edit page updates this)
  // ----------------------------------------------------------

  UserProfile profile = const UserProfile(
    name: 'Rahul Y',
    year: '3rd Year',
    programme: 'CSE - Artificial Intelligence & ML',
    studentId: 'AVIT-CSE-AIML-2024',
    email: 'rahul@student.avit.ac.in',
    phone: '',
  );

  // ----------------------------------------------------------
  // ACTIVITIES
  // ----------------------------------------------------------

  final List<Map<String, dynamic>> activities = [
    {
      'title': 'AI & Machine Learning Workshop',
      'date': '25 September 2026',
      'time': '10:00 AM',
      'location': 'AI Lab',
      'icon': Icons.smart_toy,
      'registered': false,
      'image': aiWorkshopImage,
    },
    {
      'title': 'AVIT Sports Carnival',
      'date': '28 September 2026',
      'time': '3:00 PM',
      'location': 'Sports Ground',
      'icon': Icons.sports_soccer,
      'registered': false,
      'image': sportsImage,
    },
    {
      'title': 'Career Development Programme',
      'date': '02 October 2026',
      'time': '2:00 PM',
      'location': 'AVIT Auditorium',
      'icon': Icons.work,
      'registered': false,
      'image': careerImage,
    },
  ];

  // ----------------------------------------------------------
  // HELPERS
  // ----------------------------------------------------------

  void showMessage(String message) {
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          content: Text(message),
          behavior: SnackBarBehavior.floating,
          backgroundColor: darkBlue,
          duration: const Duration(seconds: 2),
        ),
      );
  }

  void selectPage(int index) {
    setState(() => currentIndex = index);
  }

  int get registeredCount =>
      activities.where((a) => a['registered'] == true).length;

  /// Opens a full page with the AVIT app bar style (direct route).
  void openPage(String title, Widget body) {
    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => Scaffold(
          appBar: AppBar(
            title: Text(
              title,
              style: const TextStyle(fontWeight: FontWeight.bold),
            ),
            backgroundColor: primaryBlue,
            foregroundColor: Colors.white,
          ),
          body: body,
        ),
      ),
    );
  }

  // ----------------------------------------------------------
  // REGISTER / ADD / CLEAR ACTIVITIES
  // ----------------------------------------------------------

  void registerActivity(int index) {
    setState(() {
      activities[index]['registered'] = !activities[index]['registered'];
    });

    if (activities[index]['registered']) {
      showMessage('${activities[index]['title']} registered successfully!');
    } else {
      showMessage('Registration cancelled.');
    }
  }

  void addActivity() {
    setState(() {
      activities.add({
        'title': 'AVIT Innovation Meetup',
        'date': '05 October 2026',
        'time': '11:00 AM',
        'location': 'Student Activity Centre',
        'icon': Icons.lightbulb,
        'registered': false,
        'image': campusHeroImage, // every activity needs an image
      });
    });

    showMessage('New AVIT activity added successfully!');
  }

  void clearRegistrations() {
    setState(() {
      for (final a in activities) {
        a['registered'] = false;
      }
    });
    showMessage('All registrations cleared.');
  }

  // ----------------------------------------------------------
  // EDIT PROFILE (result returned with Navigator.pop)
  // ----------------------------------------------------------

  Future<void> editProfile() async {
    final updated = await Navigator.of(context).push<UserProfile>(
      MaterialPageRoute(
        builder: (_) => EditProfilePage(profile: profile),
      ),
    );

    if (updated != null) {
      setState(() => profile = updated);
      showMessage('Profile updated successfully!');
    }
  }

  // ----------------------------------------------------------
  // NAVIGATION ACTIONS
  // ----------------------------------------------------------

  void openLibrary() => openPage('Library', const LibraryPage());

  void openCafeteria() => openPage('Cafeteria', const CafeteriaPage());

  void openCampusMap() =>
      openPage('Campus Map', CampusMapPage(onSelect: showMessage));

  // Named routes (Navigator.pushNamed)
  void openHelpdesk() {
    Navigator.pushNamed(context, AppRoutes.request, arguments: profile);
  }

  void openFeedback() {
    Navigator.pushNamed(context, AppRoutes.feedback, arguments: profile);
  }

  void openCalendar() {
    Navigator.pushNamed(context, AppRoutes.calendar, arguments: activities);
  }

  void openTimetable() => Navigator.pushNamed(context, AppRoutes.timetable);

  void openServices() => Navigator.pushNamed(context, AppRoutes.services);

  Future<void> openEvents() async {
    await Navigator.pushNamed(context, AppRoutes.events, arguments: activities);
    // The Events screen may change registration state
    if (mounted) setState(() {});
  }

  Future<void> openProfileRoute() async {
    final result = await Navigator.pushNamed(
      context,
      AppRoutes.profile,
      arguments: profile,
    );
    if (result == 'edit' && mounted) editProfile();
  }

  // Direct route (Navigator.push + MaterialPageRoute)
  void openSettings() {
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => SettingsPage(
          notificationMode: notificationMode,
          onChanged: (v) => setState(() => notificationMode = v),
        ),
      ),
    );
  }

  void showNotifications() {
    switch (notificationMode) {
      case 0:
        showMessage('You have 3 new AVIT notifications');
        break;
      case 1:
        showMessage('1 important notification: Exam Registration');
        break;
      default:
        showMessage('Notifications are off. Change this in Settings.');
    }
  }

