                  child: Icon(activity['icon'], color: primaryBlue, size: 28),
                ),
                const SizedBox(width: 14),
                Expanded(
                  child: Text(
                    activity['title'],
                    style: const TextStyle(
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                      color: darkBlue,
                    ),
