                ),
              ],
            ),
            const SizedBox(height: 18),
            _detailRow(Icons.calendar_today_outlined, activity['date']),
            _detailRow(Icons.access_time, activity['time']),
            _detailRow(Icons.location_on_outlined, activity['location']),
