  Widget _drawerItem(IconData icon, String title, VoidCallback onTap) {
    return ListTile(
      leading: Icon(icon, color: primaryBlue),
      title: Text(title),
      onTap: () {
        Navigator.pop(context); // close the drawer first
        onTap();
      },
    );
  }

