  // HOME PAGE
  // ============================================================

  Widget buildHomePage() {
    return LayoutBuilder(
      builder: (context, constraints) {
        final bool wide = constraints.maxWidth >= 900;
        final double contentWidth = wide ? 1180 : double.infinity;

        return SingleChildScrollView(
          padding: EdgeInsets.fromLTRB(wide ? 28 : 16, 18, wide ? 28 : 16, 38),
          child: Center(
            child: ConstrainedBox(
              constraints: BoxConstraints(maxWidth: contentWidth),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  _websiteHero(wide),
                  const SizedBox(height: 22),
                  _quickNavRow(),
                  const SizedBox(height: 22),

                  // Profile, next class, academic snapshot, announcement
                  CampusDashboardPanel(
                    profile: profile,
                    onOpenTimetable: openTimetable,
                    onOpenAnnouncement: () => showAnnouncement(
                      Icons.campaign,
                      'Exam Registration',
                      'Semester examination registration is now open.',
                      'Register through the student portal before the '
                          'deadline. Contact the examination cell for help.',
                    ),
                  ),
                  const SizedBox(height: 30),

                  _sectionHeading(
                    eyebrow: 'QUICK ACCESS',
                    title: 'Jump to your campus tools',
                    actionLabel: 'Services',
                    onAction: openServices,
                  ),
                  const SizedBox(height: 14),
                  _quickAccessCards(wide),
                  const SizedBox(height: 34),

                  _sectionHeading(
                    eyebrow: 'AVIT AT A GLANCE',
                    title: 'A smarter way to experience your campus',
                    actionLabel: 'View Activities',
                    onAction: () => selectPage(1),
                  ),
                  const SizedBox(height: 14),
                  _statsRow(wide),
                  const SizedBox(height: 34),

                  _sectionHeading(
                    eyebrow: 'CAMPUS LIFE',
