    final cards = [
      CampusActionCard(
        icon: Icons.schedule_rounded,
        title: 'Timetable',
        subtitle: 'Your weekly classes',
        onTap: openTimetable,
      ),
      CampusActionCard(
        icon: Icons.apps_rounded,
        title: 'Services',
        subtitle: 'Browse campus services',
