  Widget _latestUpdates(bool wide) {
    final updates = [
      (
      aiWorkshopImage,
      'NextGen Innovation Workshop',
      'Agentic AI & Design Thinking',
      '22 Jul 2026',
      Icons.auto_awesome_rounded,
      ),
      (
      sportsImage,
      '12th International Yoga Day',
