      Icons.self_improvement_rounded,
      ),
      (
      cafeteriaImage,
      'Campus Events',
      'Clubs, fests and student activities',
      'This semester',
      Icons.celebration_rounded,
      ),
    ];

    if (!wide) {
      return Column(
        children: updates.map((item) => _updateCard(item)).toList(),
      );
    }

    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: updates
          .map((item) => Expanded(
        child: Padding(
          padding: EdgeInsets.only(
            right: item == updates.last ? 0 : 12,
