                    fontSize: 16,
                  ),
                ),
                const SizedBox(height: 10),
                profileItem(
                    Icons.badge_outlined, 'Student ID', profile.studentId),
                profileItem(Icons.email_outlined, 'Email', profile.email),
                profileItem(
